// Supplied genuine audience sessions are distinct from original producer admin authority.
// No caller-provided expected access labels, key impersonation or target-only sessions.
struct PgSuppliedAudience {auth:crate::auth::middleware::AuthUser,bearer:String}
impl PgSuppliedAudience{
 fn supplied(token:&str,secret:&str)->anyhow::Result<Self>{ensure!(secret.len()>=32&&!token.is_empty()&&token.len()<=8192&&!token.bytes().any(|b|b.is_ascii_whitespace()),"Invalid bounded audience credential");let claims=crate::auth::jwt::validate_token(token,secret,crate::auth::jwt::TokenType::Access).map_err(|_|fail("Actual supplied audience signature invalid"))?;let auth=crate::auth::middleware::AuthUser{claims,api_key_scopes:None};crate::spaces::access::principal_from_auth(&auth).map_err(|_|fail("Audience must be an actual human access session"))?;Ok(Self{auth,bearer:token.into()})}
}
struct PgAudienceSamplePlan {credential:PgSuppliedAudience,pages:Vec<bool>,published:Vec<bool>,grant_only:Vec<bool>,metadata_flags:Vec<Option<(bool,bool)>>,searches:Vec<bool>,global_read:bool,drafts:Vec<Option<(&'static str,bool)>>}
struct PgCanonicalAudiencePlan {source:Identity,attestation_sha:String,actor:String,session:String,samples:Vec<PgAudienceSamplePlan>}
fn pg_expected_access<T>(result:Result<T,crate::auth::routes::AppError>)->anyhow::Result<Option<T>>{match result{Ok(value)=>Ok(Some(value)),Err(crate::auth::routes::AppError::Unauthorized(_)|crate::auth::routes::AppError::Forbidden(_)|crate::auth::routes::AppError::NotFound(_))=>Ok(None),Err(error)=>bail!("Original audience policy could not be certified: {error:?}")}}
impl StoppedPgVerificationSource<'_>{
 async fn canonical_audience_plan(&mut self,pages:&PgCanonicalPagePlan,drafts:&PgCanonicalDraftPlan,supplied:Vec<PgSuppliedAudience>)->anyhow::Result<PgCanonicalAudiencePlan>{
  self.fence().await?;pages.fence(self)?;drafts.fence(self)?;ensure!(!supplied.is_empty()&&supplied.len()<=8,"Original audience plan requires1..8 genuine samples");let mut samples=Vec::new();let mut actors=std::collections::BTreeSet::new();
  for credential in supplied{let actor=crate::spaces::access::require_current_human_identity(self.conn,&credential.auth).await.map_err(|_|fail("Original audience session unavailable"))?;ensure!(actors.insert(actor.clone())&&actor!=self.admin.claims.sub,"Original audience identities must be distinct from producer/each other");let global_read=pg_expected_access(crate::spaces::access::require_current_human_read(self.conn,&credential.auth).await)?.is_some();let mut selected_pages=Vec::new();let mut published=Vec::new();let mut grant_only=Vec::new();let mut metadata_flags=Vec::new();let mut searches=Vec::new();for page in &pages.pages{let principal=crate::spaces::access::principal_from_auth(&credential.auth).map_err(|_|fail("Original audience credential expired"))?;selected_pages.push(pg_expected_access(crate::spaces::access::resolve_page_access(self.conn,principal,&page.space,&page.id,crate::spaces::access::PageOperation::View,crate::spaces::access::Purpose::Routine).await)?.is_some());let metadata=pg_expected_access(crate::spaces::shared_pages::published_view(self.conn,&credential.auth,&page.space,&page.id).await)?;published.push(metadata.is_some());grant_only.push(metadata.as_ref().is_some_and(|access|access.direct_viewer_grant.is_some()));let flags=match metadata{None=>None,Some(access) if access.direct_viewer_grant.is_some()=>Some((false,false)),Some(_)=>{let principal=crate::spaces::access::principal_from_auth(&credential.auth).map_err(|_|fail("Original metadata actor expired"))?;if pg_expected_access(crate::spaces::access::resolve_page_access(self.conn,principal,&page.space,&page.id,crate::spaces::access::PageOperation::InspectMetadata,crate::spaces::access::Purpose::Routine).await)?.is_some(){Some((crate::spaces::page_metadata::edit_allowed(self.conn,&credential.auth,&page.space,&page.id).await.map_err(|e|anyhow::anyhow!("Original identifier capability unavailable:{e:?}"))?,crate::spaces::maintenance::edit_allowed(self.conn,&credential.auth,&page.space,&page.id).await.map_err(|e|anyhow::anyhow!("Original maintenance capability unavailable:{e:?}"))?))}else{None}}};metadata_flags.push(flags);let principal=crate::spaces::access::principal_from_auth(&credential.auth).map_err(|_|fail("Original search audience credential expired"))?;let space=pg_expected_access(crate::spaces::access::resolve_space_access(self.conn,principal,&page.space,crate::spaces::access::Purpose::Routine).await)?;searches.push(global_read&&space.is_some_and(|s|s.allows(crate::spaces::access::Permission::View)));}
   let mut selected_drafts=Vec::new();for draft in &drafts.drafts{let raw=&draft.expected;let space=raw["space_id"].as_str().context("Original draft space absent")?;let doc=raw["document_id"].as_str().context("Original draft page absent")?;let id=raw["id"].as_str().context("Original draft absent")?;let principal=crate::spaces::access::principal_from_auth(&credential.auth).map_err(|_|fail("Original audience credential expired"))?;let access=pg_expected_access(crate::spaces::access::resolve_draft_access(self.conn,principal,space,doc,id,crate::spaces::access::DraftOperation::View,crate::spaces::access::Purpose::Routine).await)?;selected_drafts.push(match access{None=>None,Some(access)=>Some((match access.participation{crate::spaces::access::DraftParticipation::Owner=>"owner",crate::spaces::access::DraftParticipation::SharedEditor=>"editor",crate::spaces::access::DraftParticipation::SharedViewer=>"viewer",crate::spaces::access::DraftParticipation::RecoveryAuditRequired=>bail!("Recovery-only audience must not certify routine draft")},raw["owner_id"].as_str()==Some(actor.as_str())))});}
   samples.push(PgAudienceSamplePlan{credential,pages:selected_pages,published,grant_only,metadata_flags,searches,global_read,drafts:selected_drafts});
  }self.fence().await?;let plan=PgCanonicalAudiencePlan{source:self.root_identity()?,attestation_sha:digest(&self.serving.proof.raw_attestation),actor:self.admin.claims.sub.clone(),session:self.admin.claims.sid.clone(),samples};plan.fence(self).await?;Ok(plan)
 }
}
impl PgCanonicalAudiencePlan{
 async fn fence(&self,source:&mut StoppedPgVerificationSource<'_>)->anyhow::Result<()>{source.fence().await?;ensure!(self.source==source.root_identity()?&&self.attestation_sha==digest(&source.serving.proof.raw_attestation)&&self.actor==source.admin.claims.sub&&self.session==source.admin.claims.sid,"Original audience plan source context differs");for sample in &self.samples{ensure!(crate::spaces::access::require_current_human_identity(source.conn,&sample.credential.auth).await.map_err(|_|fail("Original sampled audience revoked/expired"))?==sample.credential.auth.claims.sub,"Original sampled audience identity differs");}source.physical()?;Ok(())}
}
async fn pg_audience_observation<T>(source:&mut StoppedPgVerificationSource<'_>,plan:&PgCanonicalAudiencePlan,process:&mut std::process::Child,work:impl std::future::Future<Output=anyhow::Result<T>>)->anyhow::Result<T>{
 plan.fence(source).await?;tokio::pin!(work);let until=tokio::time::sleep(std::time::Duration::from_secs(120));tokio::pin!(until);let mut pulse=tokio::time::interval(std::time::Duration::from_secs(3));pulse.tick().await;loop{tokio::select!{value=&mut work=>{plan.fence(source).await?;ensure!(process.try_wait()?.is_none(),"Actual PG normal process exited during audience observation");return value;},_=&mut until=>bail!("Original audience observation exceeded120s"),_=pulse.tick()=>{
 #[cfg(test)]pg_pending_sample_change(source,plan).await?;
 plan.fence(source).await?;ensure!(process.try_wait()?.is_none(),"Actual PG normal process exited while audience observation pending");}}}
}
#[cfg(test)]tokio::task_local!{static PG_PENDING_SAMPLE_CHANGE:std::cell::Cell<bool>;}
#[cfg(test)]async fn pg_pending_sample_change(source:&mut StoppedPgVerificationSource<'_>,plan:&PgCanonicalAudiencePlan)->anyhow::Result<()>{if PG_PENDING_SAMPLE_CHANGE.try_with(|v|v.replace(false)).unwrap_or(false){let sample=plan.samples.first().context("Original pending audience absent")?;sqlx::query("DELETE FROM sessions WHERE id=$1").bind(&sample.credential.auth.claims.sid).execute(&mut *source.conn).await?;}Ok(())}
#[cfg(test)]mod pg_audience_policy_controls{use super::*;#[test]fn original_internal_policy_errors_never_count_as_denial(){assert!(pg_expected_access::<()>(Err(crate::auth::routes::AppError::Forbidden("expected".into()))).unwrap().is_none());assert!(pg_expected_access::<()>(Err(crate::auth::routes::AppError::Internal("database unavailable".into()))).is_err());assert!(PgSuppliedAudience::supplied("forged bearer","strong-original-configured-disposable-key").is_err());}}
async fn pg_audience_json(client:&reqwest::Client,address:std::net::SocketAddr,token:&str,uri:&str)->anyhow::Result<(reqwest::StatusCode,serde_json::Value)>{let mut response=client.get(format!("http://{address}/api/v1{uri}")).bearer_auth(token).send().await?;let status=response.status();let mut bytes=Vec::new();while let Some(chunk)=response.chunk().await?{ensure!(bytes.len()+chunk.len()<=1024*1024,"Sampled audience response exceeds1MiB");bytes.extend_from_slice(&chunk);}Ok((status,if bytes.is_empty(){serde_json::Value::Null}else{serde_json::from_slice(&bytes)?}))}
async fn pg_verify_audiences(source:&mut StoppedPgVerificationSource<'_>,plan:&PgCanonicalAudiencePlan,process:&mut std::process::Child,address:std::net::SocketAddr,client:&reqwest::Client,pages:&PgCanonicalPagePlan,drafts:&PgCanonicalDraftPlan,assets:&PgCanonicalAssets)->anyhow::Result<()>{
 let private_words=pg_original_private_search_words(pages,drafts)?;
 for sample in &plan.samples{
  let token=&sample.credential.bearer;let(status,me)=pg_audience_observation(source,plan,process,pg_audience_json(client,address,token,"/auth/me")).await?;ensure!(status==reqwest::StatusCode::OK&&me["id"]==sample.credential.auth.claims.sub,"Actual target sampled authentication identity differs");
  for(index,page)in pages.pages.iter().enumerate(){let prefix=format!("/spaces/{}/documents/{}",urlencoding::encode(&page.space),urlencoding::encode(&page.id));let(status,metadata)=pg_audience_observation(source,plan,process,pg_audience_json(client,address,token,&prefix)).await?;if let Some(flags)=sample.metadata_flags[index]{ensure!(status==reqwest::StatusCode::OK,"Actual permitted audience page metadata refused");pg_verify_audience_metadata(&page.metadata,&pages.content[index]["published_metadata"],flags,&metadata)?;if sample.grant_only[index]{pg_verify_grant_metadata_mask(&metadata)?;}}else{ensure!(matches!(status.as_u16(),401|403|404),"Actual nonmember obtained private page metadata");}for(suffix,expected)in [("content",pages.content[index].clone()),("versions",serde_json::to_value(&page.history)?),("properties",serde_json::to_value(&page.properties)?)]{let(status,actual)=pg_audience_observation(source,plan,process,pg_audience_json(client,address,token,&format!("{prefix}/{suffix}"))).await?;if (if suffix=="content"{sample.published[index]}else{sample.pages[index]}){ensure!(status==reqwest::StatusCode::OK&&actual==expected,"Actual current audience published content/history/property differs");}else{ensure!(matches!(status.as_u16(),401|403|404),"Actual nonmember read private original page");}}
   let word=page.body.split(|c:char|!c.is_ascii_alphanumeric()).find(|v|v.len()>=8&&v.len()<=100).context("Original sampled search word absent")?;let uri=format!("/search?q={}&space_id={}&limit=100",urlencoding::encode(word),urlencoding::encode(&page.space));let(status,actual)=pg_audience_observation(source,plan,process,pg_audience_json(client,address,token,&uri)).await?;if sample.searches[index]{ensure!(status==reqwest::StatusCode::OK,"Actual source-permitted scoped search unavailable");pg_verify_sample_search(&actual,sample,pages,index,word,Some(&page.space))?;}else{ensure!(matches!(status.as_u16(),401|403|404),"Actual source-denied scoped search exposed results");}
   let global_uri=format!("/search?q={}&limit=100",urlencoding::encode(word));let(status,actual)=pg_audience_observation(source,plan,process,pg_audience_json(client,address,token,&global_uri)).await?;if sample.global_read{ensure!(status==reqwest::StatusCode::OK,"Actual source-permitted global search unavailable");pg_verify_sample_search(&actual,sample,pages,index,word,None)?;#[cfg(test)]if actual.as_array().is_some_and(|rows|!rows.is_empty()){ensure!(pg_verify_sample_search(&actual,sample,pages,index,word,Some("foreign-original-scope")).is_err(),"Actual global result must refuse another requested space");}}else{ensure!(matches!(status.as_u16(),401|403|404),"Actual source-denied global search exposed results");}
  }
  for(index,draft)in drafts.drafts.iter().enumerate(){let(status,actual)=pg_audience_observation(source,plan,process,pg_audience_json(client,address,token,&draft.uri)).await?;if let Some((role,publish))=sample.drafts[index]{let mut expected=draft.expected.clone();expected["access_role"]=role.into();expected["can_publish"]=publish.into();ensure!(status==reqwest::StatusCode::OK&&actual==expected,"Actual sampled private draft payload/participation differs");}else{ensure!(matches!(status.as_u16(),401|403|404),"Actual audience accessed original owner private draft");}}
  for word in &private_words{pg_audience_observation(source,plan,process,pg_private_default_search(client,address,token,word,sample.global_read)).await?;}
  for asset in &assets.legacy{let permitted=pg_expected_access(crate::spaces::shared_pages::asset_view(source.conn,&sample.credential.auth,&asset.space,&asset.page).await)?.is_some();asset.fence(source).await?;pg_audience_observation(source,plan,process,pg_legacy_download(client,address,Some(token),asset,permitted)).await?;asset.fence(source).await?;let uri=format!("/spaces/{}/documents/{}/attachment-versions/{}",urlencoding::encode(&asset.space),urlencoding::encode(&asset.page),urlencoding::encode(&asset.id));let(status,_)=pg_audience_observation(source,plan,process,pg_audience_json(client,address,token,&uri)).await?;ensure!(matches!(status.as_u16(),401|403|404),"Unregistered legacy ID must not fabricate immutable metadata");}
  for(index,asset)in assets.assets.iter().enumerate(){let permitted=pg_expected_access(crate::spaces::shared_pages::asset_view(source.conn,&sample.credential.auth,&asset.space,&asset.page).await)?.is_some();let version=&assets.versions[index];let uri=pg_version_file_route(&asset.space,&asset.page,&version.logical_attachment_id,&asset.id);pg_audience_observation(source,plan,process,async{let mut response=client.get(format!("http://{address}{uri}")).bearer_auth(token).send().await?;if !permitted{ensure!(matches!(response.status().as_u16(),401|403|404),"Actual nonmember retrieved exact private version");return Ok(());}ensure!(response.status()==reqwest::StatusCode::OK,"Actual permitted sampled version refused");let mut offset=0u64;let mut hash=sha2::Sha256::new();let mut scratch=[0u8;65536];while let Some(chunk)=response.chunk().await?{ensure!(offset.checked_add(chunk.len()as u64).is_some_and(|n|n<=asset.length),"Sampled exact binary exceeds original bound");for part in chunk.chunks(scratch.len()){asset.binding.fence_files().map_err(|e|anyhow::anyhow!(e))?;ensure!(physical_stamp(&asset.held)?==asset.stamp,"Original sampled binary exchanged");asset.held.read_exact_at(&mut scratch[..part.len()],offset)?;ensure!(part==&scratch[..part.len()],"Sampled exact binary retargeted");hash.update(part);offset+=part.len()as u64;}}ensure!(offset==asset.length&&hex::encode(hash.finalize())==asset.sha,"Sampled exact version SHA/length differs");Ok(())}).await?;
   let metadata_uri=format!("/spaces/{}/documents/{}/attachment-versions/{}",urlencoding::encode(&asset.space),urlencoding::encode(&asset.page),urlencoding::encode(&asset.id));let(status,metadata)=pg_audience_observation(source,plan,process,pg_audience_json(client,address,token,&metadata_uri)).await?;if permitted{ensure!(status==reqwest::StatusCode::OK&&metadata["version"]==serde_json::to_value(version)?&&metadata["current_space_id"]==asset.space&&metadata["current_document_id"]==asset.page&&metadata["current_storage_path"]==asset.path&&metadata["retirement"]==assets.retirements[index],"Actual sampled raw immutable version metadata differs");}else{ensure!(matches!(status.as_u16(),401|403|404),"Nonmember obtained private immutable version metadata");}
  }
 }plan.fence(source).await?;Ok(())
}

fn pg_verify_sample_search(actual:&serde_json::Value,sample:&PgAudienceSamplePlan,pages:&PgCanonicalPagePlan,index:usize,word:&str,scope:Option<&str>)->anyhow::Result<()>{let rows=actual.as_array().context("Actual sampled search response not array")?;ensure!(rows.iter().all(|row|pages.pages.iter().enumerate().any(|(i,page)|sample.published[i]&&scope.is_none_or(|space|page.space==space)&&row["document_id"]==page.id&&row["space_id"]==page.space)),"Actual sampled search returned inaccessible/noncanonical or wrong-space page");ensure!(rows.iter().all(|row|row["is_draft"]==false&&row["draft_id"].is_null()),"Default published search leaked draft identity");for row in rows{let i=pages.pages.iter().position(|page|row["document_id"]==page.id&&row["space_id"]==page.space).context("Original search page absent")?;if sample.grant_only[i]{for key in ["space_name","author","author_id"]{ensure!(row[key]=="","Grant-only search leaked hidden labels/actors");}for key in ["maintenance_user_id","maintenance_group_id","folder_id","folder_name","draft_id"]{ensure!(row[key].is_null(),"Grant-only search leaked private placement/ownership");}}}if sample.published[index]&&scope.is_none_or(|space|pages.pages[index].space==space){let page=&pages.pages[index];ensure!(rows.iter().any(|v|v["document_id"]==page.id&&v["space_id"]==page.space&&v["excerpt"].as_str().is_some_and(|s|s.contains(word))),"Actual permitted audience lost rebuilt search result");}Ok(())}
fn pg_verify_grant_metadata_mask(value:&serde_json::Value)->anyhow::Result<()>{ensure!(value["page_access_source"]=="direct_page_grant","Original grant metadata source label differs");for key in ["folder_id","parent_id","maintenance_user_id","maintenance_group_id","locked_by"]{ensure!(value[key].is_null(),"Grant-only metadata leaked placement/ownership");}for key in ["created_by","last_updated_by"]{ensure!(value[key]=="","Grant-only metadata leaked hidden actor");}Ok(())}

fn pg_verify_audience_metadata(expected:&serde_json::Value,published:&serde_json::Value,flags:(bool,bool),actual:&serde_json::Value)->anyhow::Result<()>{for(key,value)in expected.as_object().context("Original metadata projection absent")?{ensure!(actual.get(key)==Some(value),"Actual sampled canonical page metadata differs");}for key in ["title","icon","cover_image"]{ensure!(actual.get(key)==published.get(key),"Actual sampled published metadata differs");}ensure!(actual.get("draft_id").is_none(),"Published page metadata exposed private draft projection");ensure!(actual["identifier_edit_allowed"]==flags.0&&actual["maintenance_edit_allowed"]==flags.1,"Actual sampled metadata editing capabilities differ from original current policy");Ok(())}
#[cfg(test)]mod pg_audience_metadata_controls{use super::*;#[test]fn exact_original_metadata_and_private_projection_refuse(){let source=serde_json::json!({"id":"original","space_id":"space","title":"Original","created_at":"original-created","updated_at":"original-updated","published_at":"original-published"});let published=serde_json::json!({"title":"Original","icon":null,"cover_image":"starlane-attachment://11111111-2222-4333-8444-555555555555"});let mut actual=source.clone();actual["icon"]=published["icon"].clone();actual["cover_image"]=published["cover_image"].clone();actual["identifier_edit_allowed"]=false.into();actual["maintenance_edit_allowed"]=false.into();assert!(pg_verify_audience_metadata(&source,&published,(false,false),&actual).is_ok());let mut forged=actual.clone();forged["title"]="copied different title".into();assert!(pg_verify_audience_metadata(&source,&published,(false,false),&forged).is_err());let mut forged=actual.clone();forged["cover_image"]="starlane-attachment://11111111-2222-4333-8444-999999999999".into();assert!(pg_verify_audience_metadata(&source,&published,(false,false),&forged).is_err());let mut forged=actual.clone();forged["draft_id"]="original-owner-private-draft".into();assert!(pg_verify_audience_metadata(&source,&published,(false,false),&forged).is_err());actual["identifier_edit_allowed"]=true.into();assert!(pg_verify_audience_metadata(&source,&published,(false,false),&actual).is_err());}}

// Distinctive original private text only; words come from held canonical SQL,
// never caller-supplied labels or target results. No word/body enters a record.
fn pg_private_words(published:&str,private:&[String])->Vec<String>{let public=published.to_ascii_lowercase();let mut words=std::collections::BTreeSet::new();for body in private{if let Some(word)=body.split(|c:char|!c.is_ascii_alphanumeric()).find(|word|(3..=40).contains(&word.len())&&!public.contains(&word.to_ascii_lowercase())){words.insert(word.to_ascii_lowercase());}}words.into_iter().collect()}
fn pg_original_private_search_words(pages:&PgCanonicalPagePlan,drafts:&PgCanonicalDraftPlan)->anyhow::Result<Vec<String>>{let mut published=String::new();for page in &pages.pages{published.push_str(&page.body);published.push(' ');published.push_str(page.metadata["title"].as_str().context("Original published title absent")?);published.push(' ');}let private:Vec<String>=drafts.drafts.iter().map(|draft|Ok::<_,anyhow::Error>(format!("{} {}",draft.expected["content"].as_str().context("Original private content projection malformed")?,draft.expected["title"].as_str().context("Original private title projection malformed")?))).collect::<anyhow::Result<_>>()?;let words=pg_private_words(&published,&private);ensure!(words.len()<=256,"Original private-only query plan exceeds256");Ok(words)}
async fn pg_private_default_search(client:&reqwest::Client,address:std::net::SocketAddr,token:&str,word:&str,permitted:bool)->anyhow::Result<()>{let uri=format!("/search?q={}&limit=100",urlencoding::encode(word));let(status,result)=pg_audience_json(client,address,token,&uri).await.map_err(|_|fail("Original private default-search transport refused"))?;if permitted{ensure!(status==reqwest::StatusCode::OK&&result.as_array().is_some_and(|rows|rows.is_empty()),"Default published search exposed original private-draft-only text or identity");}else{ensure!(matches!(status.as_u16(),401|403|404),"Original source-denied actor accessed default search");}Ok(())}
async fn pg_verify_owner_private_default_search(source:&mut StoppedPgVerificationSource<'_>,process:&mut std::process::Child,address:std::net::SocketAddr,client:&reqwest::Client,token:&str,pages:&PgCanonicalPagePlan,drafts:&PgCanonicalDraftPlan)->anyhow::Result<usize>{source.fence().await?;pages.fence(source)?;drafts.fence(source)?;let auth=crate::auth::middleware::AuthUser{claims:source.admin.claims.clone(),api_key_scopes:None};let permitted=pg_expected_access(crate::spaces::access::require_current_human_read(source.conn,&auth).await)?.is_some();let words=pg_original_private_search_words(pages,drafts)?;for word in &words{pg_live_observation(source,process,pg_private_default_search(client,address,token,word,permitted)).await?;}source.fence().await?;Ok(words.len())}
#[cfg(test)]mod pg_private_search_controls{use super::*;#[test]fn private_query_words_are_original_distinct_bounded_literals(){assert_eq!(pg_private_words("Original published visible title",&["PRIVATEPGDRAFT original body".into(),"PRIVATEPGDRAFT duplicate".into()]),vec!["privatepgdraft"]);assert!(pg_private_words("shared original",&["shared original".into()]).is_empty());let long="X".repeat(41);assert!(pg_private_words("",&[long]).is_empty());assert_eq!(pg_private_words("containsOriginalToken",&["OriginalToken SECRETWORD".into()]),vec!["secretword"]);}}
